    "home_faq_q1": "एआई পুষ্টি মূল্যাঙ্কন कितना নিখুঁত है?",
    "home_faq_a1": "न्यूट्री-एआई एनएचएएनईएस क्लिनिकल डेटासेट पर 94.8% F1-स्कोर নিখুঁতता प्राप्त करता है। हमारा रैंडम फॉरेस्ट मॉडल हज़ारों वास्तविक रोगियों के रिकॉर्ड पर प्रशिक्षित है।",
    "home_faq_q2": "क्या मैं सीधे ब्लड टेस्ट पीडीएफ ৰিপোৰ্ট अपलोड कर सकता हूँ?",
    "home_faq_a2": "हाँ! हमारा मल्टी-मॉडल जेमिनी विज़न ओसीआर लैब पीडीएफ फ़ाइलों को पार्स करता है और तुरंत অভাৱ जोखिम বিশ্লেষণ के लिए आपके रक्त मार्कर मानों को स्वतः भरता है।",
    "home_faq_q3": "क्या न्यूट्री-एआई शाकाहारी और वीगन आहार का समर्थन करता है?",
