    "home_faq_a2": "हाँ! हमारा मल्टी-मॉडल जेमिनी विज़न ओसीआर लैब पीडीएफ फ़ाइलों को पार्स करता है और तुरंत कमी जोखिम विश्लेषण के लिए आपके रक्त मार्कर मानों को स्वतः भरता है।",
